],"state":{"conversationOwner":"BOT","revision":1,"currentProductId":"ST411","consideredSize":null,"salesStage":"BROWSING","factSnapshotVersion":"authored-evaluation-r4-v1","bindingVersion":"binding-r4-v1","recipient":"synthetic-recipient","permission":true,"privacyAllowed":true,"customerProfileId":"dbd89422-34f3-5cf3-af16-5a57c227fc7f","customerProfileRevision":1,"measurementFingerprint":"f902669c4fed51f75ea0d10e3bdcec65fd24d6b8bab53c25bb554da7d1aa9032"},"productProfiles":[{"ref":"profile:ST411","subjectRef":"ST411","authority":"EVALUATION_FIXTURE","sourceVersion":"authored-evaluation-r4-v1","observedAt":"2026-10-06T02:59:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z","contentHash":"97123b15be815c2319f33bc73b1612b833405648da0a034ad3b63b572c1beebb","details":{"silhouette":"Bán cả set: sơ mi dáng rộng, quần suông, lưng chun toàn vòng.","material":"65% polyester, 35% viscose; vải không co giãn. Chun kéo đo tối đa S82/M88/L94cm. Vải ít nhăn hơn linen trong thử gấp cùng điều kiện, vẫn có thể nhăn.","colors":["be","navy"],"sizeChart":["S: thành phẩm ngực áo100, eo quần thả66, mông100, dài quần96cm; hướng dẫn cơ thể ngực82–87/eo64–69/mông86–91cm.","M: ngực106, eo thả72, mông106, dài97cm; cơ thể ngực88–94/eo70–76/mông92–98cm.","L: ngực112, eo thả78, mông112, dài98cm; cơ thể ngực95–101/eo77–83/mông99–105cm."],"care":"Giặt nhẹ nước mát, phơi râm, là nhiệt thấp.","limitations":"Chun đo không phải khoảng cơ thể khuyên chọn. Bảng là hướng dẫn chọn size, không bảo đảm cảm giác mặc cho mọi người."}},{"ref":"profile:VA512","subjectRef":"VA512","authority":"EVALUATION_FIXTURE","sourceVersion":"authored-evaluation-r4-v1","observedAt":"2026-10-06T02:59:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z","contentHash":"ce6aa01fd84e88e70696654c839b681f3a08ba29bd0cc2037f09f363f99f7153","details":{"silhouette":"Váy midi chữ A, cổ vuông, tay ngắn, eo cố định, có lót toàn thân.","material":"Crepe 100% polyester, không co giãn; eo cố định, không chun.","colors":["đen","rêu"],"sizeChart":["S: thành phẩm ngực92, eo73, mông104, dài110cm; cơ thể ngực82–87/eo64–69/mông86–93cm.","M: ngực98, eo78, mông110, dài111cm; cơ thể ngực88–93/eo70–74/mông94–100cm.","L: ngực103, eo83, mông116, dài112cm; cơ thể ngực94–98/eo75–79/mông101–106cm."],"care":"Giặt nhẹ nước mát, là nhiệt thấp, không sấy nóng.","limitations":"Bảng là hướng dẫn chọn size; không bảo đảm thoải mái cho mọi người. Lót che thân váy trong ánh sáng phòng thông thường."}}]},"untrusted":{"latestCustomerMessage":"Chị ngại bó eo. Ngực 92, eo 74, mông 96cm thì em chọn giúp chị mẫu với size luôn nhé.","recentAcceptedDialogue":[{"role":"customer","text":"Chị cần đồ đi làm, ngồi nhiều, ngân sách 850k."},{"role":"shop","text":"ST411 là set quần suông lưng chun 749k, VA512 là váy eo cố định 829k."}],"retrievedText":[],"finalDraft":"Em chọn cho chị **set ST411 size M, giá 749.000đ**, trong ngân sách 850k. Áo dáng rộng, quần suông có lưng chun toàn vòng nên em ưu tiên mẫu này hơn váy VA512 eo cố định khi chị ngồi nhiều và ngại bó eo.

Size M được gợi ý theo số đo chị gửi; vải không co giãn nên khi thử chị ngồi xuống kiểm tra thêm cảm giác ở eo nhé.

Em nghiêng về **màu navy** để đi làm, dễ phối giày và túi. Navy và be size M đều còn hàng, chị thích màu nào ạ?"}}

